head.script:
scwin.screenId = "jldfil52120";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 파라미터 수신(init_recvParam) 후 iframe src 를 동적 설정(init_attrReals)한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (isurCd/bzProcsNo 확보)
        scwin.init_attrReals(); // 2) iframe_10 src 동적 설정 (파라미터 확정 후)
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52120.onpageload' });
    }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_attrReals
 * @description iframe_10 의 src 속성을 dma_pageContext 의 isurCd·bzProcsNo 로 조립한 의무보유목록 팝업 URL 로 동적 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_attrReals();
 */
scwin.init_attrReals = function () {
    const attrReals = [{
        childId: "iframe_10",
        attr: "src",
        fn: function () {
            const isurCd = String($c.data.readValue("dma_pageContext", "isurCd", { silent: true }));
            const bzProcsNo = String($c.data.readValue("dma_pageContext", "bzProcsNo", { silent: true }));
            return "/listInvstg/prtDepoInfoSearchPop.do?method=searchPrtDepoPop&isurCd=" + isurCd + "&bzProcsNo=" + bzProcsNo;
        }
    }];
    $c.util.applyAttrReals(attrReals);
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name btn_window_onclick
 * @description [닫기] 버튼 클릭 — 현재 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_window ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_window_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil52120.btn_window_onclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name setCorpInfo
 * @description iframe 팝업이 선택한 의무보유 정보를 부모창(opener)의 scwin.setPrtDepoInfo 로 전달하고 팝업을 닫는다. 부모창을 찾지 못하면 오류 내용을 알림으로 표시한다.
 * @param {String} nm 명의인 명
 * @param {String} prtDepoId 의무보유 ID
 * @param {String} prtDepoShrs 의무보유 주식수
 * @param {String} objKind 대상 구분
 * @returns {void}
 * @hidden N
 * @example await scwin.setCorpInfo(nm, prtDepoId, prtDepoShrs, objKind);
 */
scwin.setCorpInfo = async function (nm, prtDepoId, prtDepoShrs, objKind) {
    let str = "";
    str += "prtDepoId : " + prtDepoId + "\n";
    str += "nm : " + nm + "\n";
    str += "prtDepoShrs : " + prtDepoShrs + "\n";
    str += "objKind : " + objKind + "\n";
    const returnKeyRaw = $c.data.readValue("dma_pageContext", "returnKey", { ctx: true, soft: true, label: "param.returnKey" });
    const returnKeyStr = String(returnKeyRaw == null ? '' : returnKeyRaw);
    const returnKey = (returnKeyStr.indexOf('$' + '{') >= 0 ? '' : returnKeyStr);
    try {
        const openerScope = ($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function () { return null; }, scwin: {} };
        const openerScwin = openerScope.scwin || {};
        if (openerScwin !== scwin && typeof openerScwin.setPrtDepoInfo === 'function') {
            openerScwin.setPrtDepoInfo(nm, prtDepoId, prtDepoShrs, objKind);
        }
        $c.win.closePopup([nm, prtDepoId, prtDepoShrs, objKind]);
        $c.win.closePopup();
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'jldfil52120' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};
